function at(p,d){const pts=routes[p];let lo=0,hi=pts.length-1;while(lo<hi){const mid=(lo+hi)>>1;if(pts[mid].d<d)lo=mid+1;else hi=mid;}const b=pts[lo],a=pts[Math.max(0,lo-1)],t=b.d===a.d?0:Math.max(0,Math.min(1,(d-a.d)/(b.d-a.d)));return {x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t,angle:Math.atan2(b.y-a.y,b.x-a.x)};}
function rr(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}
function text(t,x,y,size=13,color='#53665e',align='left'){ctx.font=`${size>=18?'600':'500'} ${size}px sans-serif`;ctx.fillStyle=color;ctx.textAlign=align;ctx.fillText(t,x,y);ctx.textAlign='left';}
function strokeRoute(p,from,to,color,width,dash=[]){ctx.beginPath();for(let x=from;x<=to;x+=3){const y=trackY(x,p);if(x===from)ctx.moveTo(x,y);else ctx.lineTo(x,y);}ctx.lineWidth=width;ctx.strokeStyle=color;ctx.setLineDash(dash);ctx.stroke();ctx.setLineDash([]);}
function trainDraw(p,head,id,model=0){const look=E.fleet[model],dir=p<2?1:-1;for(let i=5;i>=0;i--){const pos=at(p,head-dir*i*43);ctx.save();ctx.translate(pos.x,pos.y);ctx.rotate(pos.angle+(dir===1?0:Math.PI));ctx.scale(1,.62);rr(-35,-10,43,24,7,'#253d302a');const grad=ctx.createLinearGradient(0,-13,0,13);grad.addColorStop(0,'#fff');grad.addColorStop(.45,'#ecf0ec');grad.addColorStop(1,'#b5c3c7');ctx.fillStyle=grad;ctx.beginPath();if(i===0){ctx.moveTo(-34,-12);ctx.lineTo(-8,-12);ctx.quadraticCurveTo(look.nose-8,-11,look.nose,0);ctx.quadraticCurveTo(look.nose-8,11,-8,12);ctx.lineTo(-34,12);ctx.closePath();}else if(i===5){ctx.moveTo(4,-12);ctx.lineTo(-21,-12);ctx.quadraticCurveTo(-40,-10,-44,0);ctx.quadraticCurveTo(-40,10,-21,12);ctx.lineTo(4,12);ctx.closePath();}else ctx.roundRect(-36,-12,40,24,4);ctx.fill();ctx.strokeStyle='#879b9e';ctx.lineWidth=.8;ctx.stroke();rr(-31,6,32,3,1,look.stripe);rr(-31,-9,32,3,1,look.stripe);rr(-25,-3,18,6,2,look.roof);if(model===1)rr(-23,-1,15,2,1,'#8497a3');if(i===0){ctx.fillStyle='#203c4b';ctx.beginPath();ctx.moveTo(-1,-8);ctx.lineTo(10,-4);ctx.lineTo(10,4);ctx.lineTo(-1,8);ctx.closePath();ctx.fill();}for(let j=0;j<(i===0?3:4);j++)rr(-29+j*7,-4,5,7,1,'#456477');if(i===2){ctx.strokeStyle='#536a70';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-22,-5);ctx.lineTo(-12,4);ctx.lineTo(-3,-5);ctx.stroke();}ctx.restore();}const pos=at(p,head-dir*110);rr(pos.x-34,pos.y-33,68,18,5,'#f9fbf2e8');text(id,pos.x,pos.y-20,12,'#305854','center');}
