function draw(){const bounds=canvas.parentElement?.getBoundingClientRect(),wide=globalThis.innerWidth>730;viewWidth=wide&&bounds?.height>0?Math.max(1100,Math.min(5000,720*bounds.width/bounds.height)):1100;viewPad=(viewWidth-1100)/2;const scale=Math.min(1.2,4096/viewWidth),cw=Math.round(viewWidth*scale),ch=Math.round(720*scale);if(canvas.width!==cw||canvas.height!==ch){canvas.width=cw;canvas.height=ch;}ctx.setTransform(scale,0,0,scale,viewPad*scale,0);ctx.clearRect(-viewPad,0,viewWidth,720);if(!cityLayer)cityLayer=buildCity();if(viewPad>0){for(let x=-100;x>-viewPad-100;x-=100)ctx.drawImage(cityLayer,0,0,100,720,x,0,100,720);for(let x=1100;x<1100+viewPad;x+=100)ctx.drawImage(cityLayer,1000,0,100,720,x,0,100,720);}ctx.drawImage(cityLayer,0,0);
for(let p=0;p<4;p++){strokeRoute(p,-Math.ceil(viewPad/3)*3,1103+viewPad,'#a5afa5',24);strokeRoute(p,-Math.ceil(viewPad/3)*3,1103+viewPad,'#777f75',18,[3,6]);strokeRoute(p,-Math.ceil(viewPad/3)*3,1103+viewPad,'#5f716e',11);strokeRoute(p,-Math.ceil(viewPad/3)*3,1103+viewPad,'#d5d9ce',7);}
for(let d=0;d<2;d++){if(s.locks[d].entry)strokeRoute(s.entryRoutes[d],d?700:160,d?1040:710,'#54b5a0',2);if(s.locks[d].exit)strokeRoute(s.exitRoutes[d],d?160:700,d?710:1040,'#d4b467',2);}
for(let p=0;p<4;p++){const y=ys[p],t=s.platforms[p],locked=!E.isOpen(s,p);rr(322,y-57,479,34,3,'#6a7f7524');rr(318,y-60,479,34,3,locked?'#bcc8c4':'#e7e9e2');rr(318,y-29,479,3,0,'#d9bf63');for(let x=350;x<790;x+=28){ctx.fillStyle='#cdd6d0';ctx.fillRect(x,y-57,1,25);}rr(325,y-56,25,25,4,locked?'#79909c':'#2c6caa');text(p+1,337,y-38,16,'#f4faff','center');text(p<2?'→':'←',370,y-37,20,'#587080');
for(let x=410;x<770;x+=83){rr(x,y-45,20,5,1,'#7a8c90');ctx.fillStyle='#a7b7b2';ctx.fillRect(x+2,y-42,2,4);ctx.fillRect(x+16,y-42,2,4);}
if(t&&['dwell','ready'].includes(t.phase))for(let j=0;j<12;j++){const x=390+j*30,py=y-39+(j%3)*3;ctx.fillStyle=['#637783','#a78f70','#75876f'][j%3];ctx.beginPath();ctx.arc(x,py,2,0,7);ctx.fill();ctx.fillStyle='#bdad91';ctx.beginPath();ctx.arc(x,py-2,1.2,0,7);ctx.fill();}
if(locked){ctx.fillStyle='#d6e0d250';ctx.fillRect(300,y-20,520,35);}}
ctx.lineWidth=1;ctx.strokeStyle='#61796b30';for(const x of [240,820]){ctx.beginPath();ctx.moveTo(x,210);ctx.lineTo(x,575);ctx.stroke();for(const y of ys){ctx.fillStyle='#70857b';ctx.fillRect(x-2,y-9,4,18);}}
for(let p=0;p<4;p++){const t=s.platforms[p];if(!t||t.phase==='reserved')continue;const reverse=p>=2,from=distanceAt(p,reverse?1180+viewPad:-80-viewPad),stop=distanceAt(p,reverse?440:700),end=distanceAt(p,reverse?-300-viewPad:1400+viewPad);let head=stop;if(t.phase==='entering')head=from+(stop-from)*(1-Math.pow(1-t.p,1.8));if(t.phase==='leaving')head=stop+(end-stop)*smooth(t.p);if(t.phase==='passing')head=from+(end-from)*t.p;trainDraw(p,head,t.id,t.model||0);}
if(s.failedTrain){const t=s.failedTrain,p=t.dir?2:0;trainDraw(p,distanceAt(p,t.dir?990:120),t.id,t.model||0);}
for(let d=0;d<2;d++){const y=d?500:300;for(const [x,side]of [[150,d?'exit':'entry'],[960,d?'entry':'exit']]){rr(x-8,y-32,16,23,6,'#294553');ctx.fillStyle=s.phase==='failed'&&s.failedTrain.dir===d&&side==='entry'?'#ef665f':s.locks[d][side]?'#7de1b5':'#d98372';ctx.beginPath();ctx.arc(x,y-21,4,0,7);ctx.fill();}text(d?'← 南京方向':'上海方向 →',55,y+37,12,'#426073');text(d?'← 南京方向':'上海方向 →',1035,y+37,12,'#426073','center');}
}

function frame(ts){if(!active)return;if(!document.hidden&&s.phase==='running'){if(last&&ts-last>=33){const before=s.phase;E.tick(s,Math.min((ts-last)/1000,.15));last=ts;draw();if(ts-lastUI>180){refresh();lastUI=ts;}if(before==='running'&&s.phase==='failed'){refresh();cover('调度失败 · 未及时安排站台',s.failedTrain.id+'（'+fleetName(s.failedTrain)+'）'+(s.failedTrain.through?'需要通过':'需要停靠')+'本站。到站倒计时已结束，列车停在'+(s.failedTrain.dir?'右侧':'左侧')+'进站信号灯前。请在倒计时归零前点击空闲站台的接车按钮。','重新值班');}if(before==='running'&&s.phase==='won'){refresh();cover('值班完成，全部安全送达！','接送 '+s.goal+' 列、通过 '+s.passed+' 列高铁 · '+s.score+' 分 · 用时 '+format(s.elapsed)+'。下一班会有不同的列车请求。','再值一班 →');}}else if(!last)last=ts;}else last=0;raf=requestAnimationFrame(frame);}
if(typeof ResizeObserver!=='undefined')new ResizeObserver(()=>draw()).observe(canvas.parentElement);
refresh();draw();
